//+------------------------------------------------------------------+
//| CCppiMath::Floor                                                 |
//+------------------------------------------------------------------+
double
CCppiMath::Floor(
const
double
v0,
const
double
floor_pct,
const
double
peak_equity,
const
double
ratchet_pct)
  {
//--- the base floor is a fixed fraction of the capital the strategy started with
double
base_floor = v0*floor_pct;
//--- ratchet_pct<=0 means the ratchet feature is disabled -- floor never moves
if
(ratchet_pct <=
0.0
)
return
(base_floor);
//--- with the ratchet enabled the floor also tracks a fraction of the highest
//--- equity ever seen, so realized gains get locked in and the floor can only rise
double
ratchet_floor = peak_equity*ratchet_pct;
return
(
MathMax
(base_floor,ratchet_floor));
  }
//+------------------------------------------------------------------+
//| CCppiMath::Cushion                                               |
//+------------------------------------------------------------------+
double
CCppiMath::Cushion(
const
double
equity,
const
double
floor_value)
  {
//--- the cushion is the only capital CPPI is allowed to put at risk; it can
//--- never be negative, even on a tick where equity sits below the floor
return
(
MathMax
(equity - floor_value,
0.0
));
  }
//+------------------------------------------------------------------+
//| CCppiMath::TargetNotional                                        |
//+------------------------------------------------------------------+
double
CCppiMath::TargetNotional(
const
double
cushion,
const
double
multiplier,
const
double
equity,
const
double
max_leverage)
  {
//--- raw target is the textbook CPPI rule: multiplier times the cushion
double
raw = multiplier*cushion;
//--- a hard ceiling on risky exposure regardless of what the multiplier wants,
//--- so an aggressive multiplier can never silently turn into unlimited leverage
double
cap = equity*max_leverage;
return
(
MathMin
(
MathMax
(raw,
0.0
),cap));
  }
//+------------------------------------------------------------------+
//| CCppiMath::MaxSingleStepDrawdown                                 |
//+------------------------------------------------------------------+
double
CCppiMath::MaxSingleStepDrawdown(
const
double
multiplier)
  {
//--- 1/m is the largest single-step drop the risky asset can take before the
//--- cushion is wiped out between rebalances; CheckGapRisk() below uses it
//--- as the threshold of its early-warning tier
if
(multiplier <=
0.0
)
return
(
0.0
);
return
(
1.0
/multiplier);
  }
CCppiEngine: the fields that carry the whole strategy
This is where CPPI stops being a formula and starts being a trading engine.
CCppiEngine
owns a
CTrade
instance, the symbol it's trading, every configured parameter, and the running state — initial equity, peak equity, the current floor, and what things looked like on the previous tick, so
CheckGapRisk()
further down actually has a "before" to compare "now" against. I'd rather just show the member list than describe it: read it top to bottom and you've got the whole answer to "what does this thing need to remember."
//+------------------------------------------------------------------+
//| CCppiEngine -- live account-driven CPPI allocation engine        |
//| CCppiEngine drives one live CPPI allocation on a single symbol.  |
//| Start() records the account's initial equity as V0. OnNewTick()  |
//| reads live equity, updates the floor and cushion, and rebalances |
//| the risky position toward multiplier*cushion whenever the drift  |
//| exceeds the configured band. Once the cushion hits zero the      |
//| engine flattens and locks -- it will not re-lever until Start()  |
//| is called again.                                                 |
//+------------------------------------------------------------------+
class
CCppiEngine
  {
private
:
   CTrade            m_trade;
// order-sending wrapper
string
m_symbol;
// risky asset traded by this engine
double
m_multiplier;
// CPPI multiplier m
double
m_floor_pct;
// base floor as a fraction of initial equity V0
double
m_ratchet_pct;
// 0 disables ratchet; else floor tracks this fraction of peak equity
double
m_max_leverage;
// hard cap on risky exposure as a multiple of equity
double
m_rebalance_band_pct;
// minimum drift, as a fraction of equity, needed to trigger a rebalance
ulong
m_magic;
// magic number stamped on every order this engine sends
uint
m_deviation_pts;
// maximum acceptable slippage per order, in points
string
m_comment;
// order comment stamped on every order
double
m_initial_equity;
// V0, captured once by Start()
double
m_peak_equity;
// highest equity observed since Start(), feeds the ratchet
double
m_floor;
// current floor F_t
double
m_prev_equity;
// equity as of the previous OnNewTick() call
double
m_prev_cushion;
// cushion as of the previous OnNewTick() call
ENUM_CPPI_STATE   m_state;
// current lifecycle state
string
m_last_error;
// human-readable reason for the most recent failure
double
CurrentExposureLots(
void
);
