void
CCppiEngine::GetSnapshot(SCppiSnapshot &snap)
  {
//--- every field is recomputed from live account and symbol data, floor
//--- included, so a snapshot never depends on OnNewTick() having run first.
//--- The peak is taken as the larger of the stored peak and current equity,
//--- without writing anything back into the engine's own state
snap.time            =
TimeCurrent
();
   snap.equity          =
AccountInfoDouble
(
ACCOUNT_EQUITY
);
double
peak          =
MathMax
(m_peak_equity,snap.equity);
   snap.floor_value     = CCppiMath::Floor(m_initial_equity,m_floor_pct,peak,m_ratchet_pct);
   snap.cushion         = CCppiMath::Cushion(snap.equity,snap.floor_value);
   snap.target_notional = CCppiMath::TargetNotional(snap.cushion,m_multiplier,snap.equity,m_max_leverage);
double
price         =
SymbolInfoDouble
(m_symbol,
SYMBOL_ASK
);
double
contract_size =
SymbolInfoDouble
(m_symbol,
SYMBOL_TRADE_CONTRACT_SIZE
);
   snap.target_lots     = NotionalToLots(snap.target_notional,price,contract_size);
   snap.actual_lots     = CurrentExposureLots();
   snap.state           = m_state;
  }
